export function ServiceAreasMap() {
  const prefersReducedMotion = useReducedMotion();

  return (
    <motion.svg
      viewBox="0 0 800 700"
      xmlns="http://www.w3.org/2000/svg"
      aria-label="Map of Florida — SJB Outdoor Living service areas"
      role="img"
      initial={prefersReducedMotion ? { opacity: 1 } : { opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
      style={{ width: "100%", height: "auto", display: "block", overflow: "visible" }}
    >
      <title>SJB Outdoor Living Florida service areas</title>

      {/* State outline */}
      <motion.path
        d={FLORIDA_PATH}
        fill="rgba(174,132,55,0.06)"
        stroke="var(--rich-warm)"
        strokeWidth="1.5"
        vectorEffect="non-scaling-stroke"
        fillRule="evenodd"
        initial={prefersReducedMotion ? { pathLength: 1 } : { pathLength: 0 }}
        animate={{ pathLength: 1 }}
        transition={{ duration: 1.8, ease: [0.16, 1, 0.3, 1] }}
      />

      {/* Static dots */}
      {SERVICE_AREA_DOTS.map((area, i) => (
        <motion.circle
          key={area.name}
          cx={area.cx}
          cy={area.cy}
          r="16"
          fill="var(--rich-warm)"
          initial={prefersReducedMotion ? { opacity: 1, scale: 1 } : { opacity: 0, scale: 0 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{
            duration: 0.45,
            delay: prefersReducedMotion ? 0 : 0.9 + i * 0.04,
            ease: [0.16, 1, 0.3, 1],
          }}
        >
          <title>{area.name}</title>
        </motion.circle>
      ))}
    </motion.svg>
  );
}
